// ezrá · lector de fuentes autorizadas. Lo que llega de la web son DATOS, nunca
// instrucciones: solo se extraen título, enlace y fecha. No se copian textos ni
// imágenes. Se respeta robots.txt y solo se leen RSS (o el RSS que anuncie un
// sitio propio). Nada de redes sociales.
const body = $input.first().json.body || {};
if (body.action !== "find_ideas" || body.mode !== "live" || !Array.isArray(body.sources)) return [];
const UA = "ezra-spotmi/0.1 (lector de fuentes autorizadas por su propietario)";
const PER_SOURCE = Math.min(Number(body.maxIdeasPerSource) || 5, 5);
const MAX_CHARS = 2 * 1024 * 1024;
const FEED_ACCEPT = "application/rss+xml, application/atom+xml, application/xml, text/xml, text/html;q=0.5";

const get = async (url, accept) => {
  const res = await this.helpers.httpRequest({
    method: "GET",
    url,
    headers: { "User-Agent": UA, Accept: accept },
    timeout: 6000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    json: false,
    encoding: "text",
  });
  const text = typeof res.body === "string" ? res.body : String(res.body ?? "");
  return { status: res.statusCode, text: text.slice(0, MAX_CHARS), tooBig: text.length > MAX_CHARS };
};
const host = (u) => new URL(u).hostname.toLowerCase().replace(/^www\./, "");
const sameSite = (a, b) => host(a) === host(b) || host(a).endsWith("." + host(b));

// robots.txt: el grupo de ezra-spotmi manda sobre el de "*"; gana la regla más
// larga y, si empatan, Allow. Si no se puede consultar (5xx o red), no se lee.
const robotsCache = {};
async function robotsAllows(target) {
  const u = new URL(target);
  if (!(u.origin in robotsCache)) {
    try {
      const r = await get(u.origin + "/robots.txt", "text/plain");
      robotsCache[u.origin] = r.status >= 500 ? null : r.status >= 400 ? "" : r.text;
    } catch (e) {
      robotsCache[u.origin] = null;
    }
  }
  const txt = robotsCache[u.origin];
  if (txt === null) return false;
  const rules = { own: [], star: [] };
  let agents = [];
  let lastWasAgent = false;
  for (const raw of txt.split(/\r?\n/)) {
    const m = raw.replace(/#.*/, "").trim().match(/^([A-Za-z-]+)\s*:\s*(.*)$/);
    if (!m) continue;
    const key = m[1].toLowerCase();
    const value = m[2].trim();
    if (key === "user-agent") {
      if (!lastWasAgent) agents = [];
      agents.push(value.toLowerCase());
      lastWasAgent = true;
      continue;
    }
    lastWasAgent = false;
    if (key !== "allow" && key !== "disallow") continue;
    if (key === "disallow" && value === "") continue;
    const rule = { allow: key === "allow", path: value };
    if (agents.some((a) => a.startsWith("ezra-spotmi"))) rules.own.push(rule);
    if (agents.includes("*")) rules.star.push(rule);
  }
  const list = rules.own.length ? rules.own : rules.star;
  const path = u.pathname + u.search;
  let best = null;
  for (const r of list) {
    const pattern = r.path.replace(/[.+?^{}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*");
    const regex = new RegExp("^" + (pattern.endsWith("$") ? pattern : pattern));
    if (!regex.test(path)) continue;
    if (!best || r.path.length > best.path.length || (r.path.length === best.path.length && r.allow))
      best = r;
  }
  return !best || best.allow;
}

const decode = (s) =>
  s
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1")
    .replace(/<[^>]*>/g, " ")
    .replace(/&#(\d+);/g, (_, n) => (Number(n) < 0x110000 ? String.fromCodePoint(Number(n)) : " "))
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&amp;/g, "&")
    .replace(/\s+/g, " ")
    .trim();
const isFeed = (t) => /<(rss|feed|rdf:RDF)[\s>]/i.test(t.slice(0, 4000));
function discover(html, pageUrl) {
  for (const tag of html.match(/<link[^>]+>/gi) || []) {
    if (!/type=["']application\/(rss|atom)\+xml["']/i.test(tag)) continue;
    const m = tag.match(/href=["']([^"']+)["']/i);
    if (!m) continue;
    try {
      return new URL(m[1].replace(/&amp;/g, "&"), pageUrl).href;
    } catch (e) {
      /* enlace inválido: se ignora */
    }
  }
  return null;
}
function parseFeed(xml, feedUrl) {
  const blocks = xml.match(/<item[\s>][\s\S]*?<\/item>/gi) || xml.match(/<entry[\s>][\s\S]*?<\/entry>/gi) || [];
  const out = [];
  for (const b of blocks) {
    if (out.length >= PER_SOURCE) break;
    const title = decode((b.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || "").slice(0, 200);
    let link = decode((b.match(/<link(?:\s[^>]*)?>([\s\S]*?)<\/link>/i) || [])[1] || "");
    if (!link) {
      const alt =
        b.match(/<link[^>]*rel=["']alternate["'][^>]*href=["']([^"']+)["']/i) ||
        b.match(/<link[^>]*href=["']([^"']+)["'][^>]*rel=["']alternate["']/i) ||
        b.match(/<link[^>]*href=["']([^"']+)["']/i);
      link = alt ? alt[1] : "";
    }
    const date = decode((b.match(/<(pubDate|published|updated|dc:date)[^>]*>([\s\S]*?)<\/\1>/i) || [])[2] || "");
    try {
      link = new URL(link.replace(/&amp;/g, "&"), feedUrl).href;
    } catch (e) {
      continue;
    }
    if (title) out.push({ title, url: link, publishedAt: date ? date.slice(0, 80) : null });
  }
  return out;
}

const ideas = [];
const skipped = [];
const skip = (s, reason) => skipped.push({ sourceId: s.id, reason });
for (const s of body.sources.slice(0, 10)) {
  try {
    let url = String(s.url || "");
    if (!url.startsWith("https://")) { skip(s, "solo se leen direcciones https"); continue; }
    if (!(await robotsAllows(url))) { skip(s, "robots.txt no permite leer esta dirección o no se pudo consultar"); continue; }
    let page = await get(url, FEED_ACCEPT);
    if (page.tooBig) { skip(s, "la respuesta es demasiado grande"); continue; }
    if (page.status >= 400) { skip(s, "el sitio respondió HTTP " + page.status); continue; }
    if (!isFeed(page.text)) {
      if (s.kind !== "owned") { skip(s, "la dirección no es un RSS"); continue; }
      const feed = discover(page.text, url);
      if (!feed || !feed.startsWith("https://") || !sameSite(feed, url)) { skip(s, "el sitio no anuncia un RSS propio"); continue; }
      if (!(await robotsAllows(feed))) { skip(s, "robots.txt no permite leer el RSS del sitio"); continue; }
      page = await get(feed, FEED_ACCEPT);
      url = feed;
      if (page.tooBig || page.status >= 400 || !isFeed(page.text)) { skip(s, "el RSS anunciado no se pudo leer"); continue; }
    }
    for (const item of parseFeed(page.text, url)) ideas.push({ sourceId: s.id, ...item });
  } catch (e) {
    skip(s, "no se pudo leer (tiempo agotado o error de red)");
  }
}
return [{ json: { jobId: body.jobId, mode: "live", status: "completed", ideas, skipped, errorCode: null, attempt: 1, completedAt: new Date().toISOString() } }];
